<script setup lang="ts">
import { onMounted, ref, watch } from "vue";
import AppBreadcrumb from "@/components/AppBreadcrumb.vue";
import ConfirmDialog from "@/components/ConfirmDialog.vue";
import PageHeader from "@/components/PageHeader.vue";
import StatusBadge from "@/components/StatusBadge.vue";
import { createUser, getUser, listProfiles, listUsers, toggleUser, updateUser, type Profile, type User, type UserPayload } from "@/services/usuarios";

const items = ref<User[]>([]); const profiles = ref<Profile[]>([]); const search = ref(""); const estado = ref("all"); const page = ref(1);
const pagination = ref({ page: 1, pageSize: 10, total: 0, totalPages: 0 }); const loading = ref(false); const saving = ref(false); const error = ref(""); const formError = ref(""); const success = ref(""); const editing = ref<User | null>(null); const showForm = ref(false); const confirmTarget = ref<User | null>(null);
const form = ref({ nombreUsuario: "", correoElectronico: "", nombreAcceso: "", identificadorInstitucional: "", password: "", profileIds: [] as number[] });
const message = (value: unknown) => value instanceof Error ? value.message : "Ocurrió un error inesperado";
async function load() { loading.value = true; error.value = ""; try { const result = await listUsers(search.value, page.value, estado.value); items.value = result.items; pagination.value = result.pagination; } catch (cause) { error.value = message(cause); } finally { loading.value = false; } }
async function loadProfiles() { try { profiles.value = await listProfiles(); } catch (cause) { error.value = message(cause); } }
async function edit(item: User | null) { editing.value = item; formError.value = ""; if (item) { try { const detail = await getUser(item.idUsuario); editing.value = detail; item = detail; } catch (cause) { error.value = message(cause); return; } } form.value = { nombreUsuario: item?.nombreUsuario ?? "", correoElectronico: item?.correoElectronico ?? "", nombreAcceso: item?.nombreAcceso ?? "", identificadorInstitucional: item?.identificadorInstitucional ?? "", password: "", profileIds: item?.perfiles.map(profile => profile.idPerfil) ?? [] }; showForm.value = true; }
function payload(): UserPayload { const value = form.value; return { nombreUsuario: value.nombreUsuario, correoElectronico: value.correoElectronico, nombreAcceso: value.nombreAcceso, identificadorInstitucional: value.identificadorInstitucional || null, profileIds: value.profileIds, ...(value.password ? { password: value.password } : {}) }; }
async function save() { formError.value = ""; saving.value = true; try { const creating = !editing.value; if (creating) await createUser(payload()); else await updateUser(editing.value!.idUsuario, payload()); showForm.value = false; success.value = creating ? "Usuario creado correctamente." : "Usuario actualizado correctamente."; await load(); } catch (cause) { formError.value = message(cause); } finally { saving.value = false; } }
function askToggle(item: User) { confirmTarget.value = item; }
async function toggle() { const item = confirmTarget.value; if (!item) return; confirmTarget.value = null; try { await toggleUser(item.idUsuario, !item.estadoUsuario); success.value = `Usuario ${item.estadoUsuario ? "desactivado" : "activado"} correctamente.`; await load(); } catch (cause) { error.value = message(cause); } }
function changePage(nextPage: number) { page.value = nextPage; void load(); }
watch([search, estado], () => { page.value = 1; void load(); });
onMounted(() => { void Promise.all([load(), loadProfiles()]); });
</script>

<template>
  <AppBreadcrumb :items="[{ label: 'Administración' }, { label: 'Usuarios' }]" />
  <PageHeader eyebrow="Administración" title="Usuarios" description="Administre las cuentas locales y sus perfiles de acceso." action-label="Nuevo usuario" @action="edit(null)" />
  <div v-if="success" class="bo-notice bo-notice-success">{{ success }}</div><div v-if="error" class="bo-state bo-state-error">{{ error }} <button class="bo-link" @click="load">Reintentar</button></div>
  <section class="bo-card"><form class="bo-toolbar" @submit.prevent="load"><input v-model="search" placeholder="Buscar por nombre, usuario o correo..." aria-label="Buscar usuarios" /><select v-model="estado" aria-label="Filtrar por estado"><option value="all">Todos los estados</option><option value="active">Activos</option><option value="inactive">Inactivos</option></select><button class="bo-btn bo-btn-primary">Filtrar</button></form><div v-if="loading" class="bo-state">Cargando usuarios...</div><div v-else-if="!items.length" class="bo-state"><strong>No hay usuarios registrados.</strong><span>Ajuste los filtros o cree un nuevo usuario.</span></div><div v-else class="bo-table-wrap"><table><thead><tr><th>Usuario</th><th>Acceso</th><th>Correo</th><th>Perfiles</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in items" :key="item.idUsuario"><td><strong>{{ item.nombreUsuario }}</strong><br /><small>{{ item.identificadorInstitucional || "Sin identificador" }}</small></td><td>{{ item.nombreAcceso }}</td><td>{{ item.correoElectronico }}</td><td>{{ item.perfiles.map(profile => profile.nombrePerfil).join(", ") || "Sin perfiles" }}</td><td><StatusBadge :active="item.estadoUsuario" /></td><td><div class="bo-actions"><button class="bo-action" @click="edit(item)">Editar</button><button class="bo-action" :class="{ danger: item.estadoUsuario }" @click="askToggle(item)">{{ item.estadoUsuario ? "Desactivar" : "Activar" }}</button></div></td></tr></tbody></table></div><footer v-if="!loading" class="bo-pagination"><span>{{ pagination.total }} registros · Página {{ pagination.page }} de {{ Math.max(pagination.totalPages, 1) }}</span><div><button class="bo-page-button" :disabled="page <= 1" @click="changePage(page - 1)">Anterior</button><button class="bo-page-button" :disabled="page >= pagination.totalPages" @click="changePage(page + 1)">Siguiente</button></div></footer></section>
  <div v-if="showForm" class="bo-modal-backdrop" @click.self="showForm = false"><section class="bo-modal"><header><div><span class="bo-eyebrow">{{ editing ? "Editar registro" : "Nuevo registro" }}</span><h2>{{ editing ? "Editar usuario" : "Crear usuario" }}</h2></div><button class="bo-close" type="button" @click="showForm = false">×</button></header><p v-if="formError" class="bo-form-error">{{ formError }}</p><form class="bo-form" @submit.prevent="save"><div class="bo-form-grid"><label>Nombre completo *<input v-model="form.nombreUsuario" maxlength="150" required /></label><label>Nombre de acceso *<input v-model="form.nombreAcceso" maxlength="90" required /></label><label>Correo electrónico *<input v-model="form.correoElectronico" type="email" maxlength="150" required /></label><label>Identificador institucional<input v-model="form.identificadorInstitucional" maxlength="50" /></label><label class="bo-form-wide">{{ editing ? "Nueva contraseña (opcional)" : "Contraseña *" }}<input v-model="form.password" type="password" minlength="8" maxlength="200" :required="!editing" autocomplete="new-password" /></label></div><fieldset class="bo-profile-list"><legend>Perfiles asignados *</legend><label v-for="profile in profiles" :key="profile.idPerfil"><input v-model="form.profileIds" type="checkbox" :value="profile.idPerfil" /> {{ profile.codigoPerfil }} · {{ profile.nombrePerfil }}</label></fieldset><footer class="bo-form-actions"><button class="bo-btn" type="button" @click="showForm = false">Cancelar</button><button class="bo-btn bo-btn-primary" :disabled="saving || !form.profileIds.length">{{ saving ? "Guardando..." : "Guardar usuario" }}</button></footer></form></section></div>
  <ConfirmDialog :open="Boolean(confirmTarget)" title="Cambiar estado del usuario" :message="confirmTarget ? `¿Desea ${confirmTarget.estadoUsuario ? 'desactivar' : 'activar'} a ${confirmTarget.nombreUsuario}?` : ''" :confirm-label="confirmTarget?.estadoUsuario ? 'Desactivar' : 'Activar'" @confirm="toggle" @cancel="confirmTarget = null" />
</template>
